import 'dart:io';
import 'dart:convert';
import 'package:sdp_transform/sdp_transform.dart';

void main() async {
  final contents = await File('./test/ssrc.sdp').readAsString();
  final session = parse(contents);
  print(json.encode(session));
  final sdp = write(session, null);
  print(sdp);
}
